components.customDefaultValue:
let loondienst = [];
if (data.pv?.inkomstenVanuitAanvraag?.loondienst?.length > 0) {
  loondienst = data.pv.inkomstenVanuitAanvraag.loondienst.map(loon => {
    return {
      primairInkomstencomponentType: {
        "code": "3",
        "name": "Betaald werk"
      },
      naam: loon?.bedrijfsNaam,
      nettoInkomsten: loon?.nettoLoon,
      periodiciteitUitbetaling: loon?.periodiciteitUitbetalingLoon,
      soortContract: loon?.soortContract,
      indicatieMaaltijdvergoeding: loon?.additioneleVergoedingen.some(item => item.code === "MAALTIJDVERGOEDING"),
      maaltijdvergoedingNettoInkomsten: loon?.maaltijdvergoeding,
      indicatieOnkostenvergoeding: loon?.additioneleVergoedingen.some(item => item.code === "ONKOSTENVERGOEDING"),
      onkostenvergoedingNettoInkomsten: loon?.onkostenvergoeding,
      indicatieReiskostenvergoeding: loon?.additioneleVergoedingen.some(item => item.code === "REISKOSTENVERGOEDING"),
      reiskostenvergoedingNettoInkomsten: loon?.reiskostenvergoeding,
      indicatieVergoedingInNatura: loon?.additioneleVergoedingen.some(item => item.code === "NATURA"),
      naturaNettoInkomsten: loon?.waardeLoonInNatura,
      indicatieHeffingskorting: loon?.loonheffingskorting.code === '1',
      indicatieUrenVermindering: loon?.urenvermindering.code === '1'
    };
  });
}
value = loondienst;

const threeMonthsAgo = moment(data.gegevensVanuitAanvraag?.startDatum).subtract(3, 'months');
value = (data.pv?.inkomstenVanuitBronnen?.loondienst ?? []).map(item => ({ ...item, opgaven: item.opgaven.filter(opgave => { 
  if (!opgave.datumEindOpgave && opgave.datumEindOpgave !== '') return false; 
  const datumEind = moment(opgave.datumEindOpgave); 
  return threeMonthsAgo.isSameOrBefore(datumEind); }) 

}));

components.calculateValue:
let totaal = 0;

if(!isNaN(Number(row?.nettoInkomsten))) {
  totaal += Number(row?.nettoInkomsten);
}

// AVWB Budget
if(row?.indicatieAVWBBudget === true && !isNaN(Number(row?.avwbNettoInkomsten))) {
  totaal += Number(row?.avwbNettoInkomsten);
}

// Vakantiegeld
if(row?.indicatieVakantiegeld === true && !isNaN(Number(row?.vakantiegeldNettoInkomsten))) {
  totaal += Number(row?.vakantiegeldNettoInkomsten);
}

// Maaltijdvergoeding
if(row?.indicatieMaaltijdvergoeding === true && !isNaN(Number(row?.maaltijdvergoedingNettoInkomsten))) {
  totaal += Number(row?.maaltijdvergoedingNettoInkomsten);
}

// Onkostenvergoeding
if(row?.indicatieOnkostenvergoeding === true && !isNaN(Number(row?.onkostenvergoedingNettoInkomsten))) {
  totaal += Number(row?.onkostenvergoedingNettoInkomsten);
}

// Reiskostenvergoeding
if(row?.indicatieReiskostenvergoeding === true && !isNaN(Number(row?.reiskostenvergoedingNettoInkomsten))) {
  totaal += Number(row?.reiskostenvergoedingNettoInkomsten);
}

// Vergoeding in natura
if(row?.indicatieVergoedingInNatura === true && !isNaN(Number(row?.naturaNettoInkomsten))) {
  totaal += Number(row?.naturaNettoInkomsten);
}

value = totaal;

let totaal = 0;
let totaalNettoInkomsten = Number(row?.totaalNettoInkomsten);
if (totaalNettoInkomsten >= 0 && row?.periodiciteitUitbetaling) {
 if (row.periodiciteitUitbetaling.code === '1') {
    totaal = totaalNettoInkomsten * 260 / 12;
  } else if (row.periodiciteitUitbetaling.code === '2') {
    totaal = (totaalNettoInkomsten * 52 / 12);
  } else if (row.periodiciteitUitbetaling.code === '4') {
    totaal = totaalNettoInkomsten * 13 / 12;
  } else if (row.periodiciteitUitbetaling.code === '6') {
    totaal = totaalNettoInkomsten;
  } else if (row.periodiciteitUitbetaling.code === '7') {
    totaal = (totaalNettoInkomsten / 3);
  } else if (row.periodiciteitUitbetaling.code === '8') {
    totaal = (totaalNettoInkomsten / 12);
  } 
} 

value = totaal;

let totaalStap = 0;
if (data.pv?.arbeid?.inkomstenComponenten?.length > 0) {
   totaalStap = data.pv?.arbeid?.inkomstenComponenten?.map(loondienst => Number(loondienst?.totaalNettomaandelijkseInkomsten) || 0)?.reduce((sum, n) => sum + n, 0) ?? 0;
}
value = Number(totaalStap);
